/**
 * Serbian, Latin script, ijekavian.
 *
 * Typed as a complete map of {@link MessageKey}, so leaving a key out fails the
 * build. Cyrillic, if it is ever wanted, is a mechanical transliteration of
 * this file rather than a second translation effort.
 *
 * Terminology follows what is actually said on a site rather than a literal
 * translation: a vehicle or tool is "zaduženo" (signed out to someone) and
 * "razduženo" (handed back), which is the wording used on the paperwork.
 */
