  'guide.title': 'Kako se koristi platforma',
  'guide.tabUsage': 'Korišćenje platforme',
  'guide.tabRoles': 'Uloge',
  'guide.tabBranches': 'Poslovne jedinice',
  'guide.branches.step1': 'Poslovna jedinica je dio vaše vlastite organizacije: filijala, predstavništvo ili zasebno pravno lice grupe. Nije firma klijenta. Sve je na jednoj stranici, Administracija > Firma i poslovne jedinice: podaci firme i jedinice, na dvije kartice.',
  'guide.branches.step2': 'Dodajte jedinicu s nazivom, bojom i tipom. Zasebno pravno lice koristi samo svoje poreske brojeve; predstavništvo koristi brojeve firme gdje nema svojih. Poreske brojeve upisuje samo Super Admin, a vide ih samo oni kojima je to pravo dodijeljeno.',
  'guide.branches.step3': 'Na redu jedinice, "Dodijeli gradilišta" premješta glavna gradilišta u nju (podgradilišta slijede). Jedinica gradilišta može se birati i u njegovom obrascu.',
  'guide.branches.step4': '"Dodijeli zaposlene" dovodi ljude: označite ih i za prvo punjenje ostavite uključeno "od datuma zaposlenja", da ono što su ranije radili ne ostane bez jedinice. Pomjeraju se samo označeni; radnja je sve ili ništa.',
  'guide.branches.step5': 'Zaposlenje u jedinici ima datume. Prebacivanje zatvara prethodnu jedinicu dan ranije, pa prošli sati ostaju gdje su odrađeni. Datum koji se ne uklapa u istoriju se odbija; grešku ispravite brisanjem pogrešnog perioda na stranici zaposlenog.',
  'guide.branches.step6': 'Vozila, alat, ostali troškovi, ručne isplate, prihodi firme i smještaj imaju polje "Poslovna jedinica". Prazno znači da prati svoje gradilište.',
  'guide.branches.step7': 'Izbornik u zaglavlju sužava liste, troškove, prihode i početnu stranicu na jednu jedinicu. Kad je jedinica odabrana, sate i plate računate po Gradilištu (gdje su odrađeni) ili po Poslodavcu (jedinica koja je tog dana zapošljavala osobu). Sve ostalo je vlastito jedinici u oba slučaja.',
  'guide.branches.step8': 'Izvozi završavaju kolonom "Poslovna jedinica" i prate izbornik. Na listi faktura, "Pregled / štampa" otvara pregled s podacima jedinice koja izdaje. To je izvod iz evidencije, ne faktura koju izdaje knjigovodstvo.',
  'guide.branches.step9': 'Mjesečni platni spisak (Evidencija) može pripadati jedinici; njen prvi nacrt sadrži ljude koje je ta jedinica zapošljavala u mjesecu, a provjere označavaju svakoga koga nije zapošljavala.',
  'guide.branches.step10': 'Zaposleni dobija obavijest kad mu se promijeni jedinica. Obavijesti se mogu uputiti jednoj jedinici. Lista "Još treba podesiti" na početnoj stranici broji ljude i gradilišta bez jedinice. Cijeli vodič: docs/VODIC_POSLOVNE_JEDINICE.md.',
  'guide.usage.step1': 'Prijavite se sa svojim email-om i lozinkom na stranici za prijavu.',
  'guide.usage.step2':
    'Izaberite sekciju sa trake ikonica lijevo. Zadržite miš preko ikonice grupe (npr. Troškovi) da vidite njene stranice, ili kliknite da odmah odete na glavnu.',
  'guide.usage.step3':
    'Svaka lista ima dugme "+" za dodavanje novog zapisa, a klik na red otvara detalje ili izmjenu.',
  'guide.usage.step4':
    'Pritisnite Ctrl+K (ili lupu) da pretražite stranice i zapise ili da započnete nešto novo: evidentirate trošak, prijavite odsustvo, dodate zaposlenog. Stranice koje čekaju na vas prikazuju broj.',
  'guide.usage.step5':
    'Ikonica zvona pokazuje obavještenja — nove zahtjeve, dokumente koji ističu i sve ostalo što čeka na vas.',
  'guide.usage.step6':
    'Jezik interfejsa mijenjate ikonicom globusa gore desno — sve se odmah prevodi.',
  'guide.usage.step7':
    'Troškovi: sve evidencije troškova (vozila, alati, ostali, materijal, smještaj, finansije) su pod "Unosi troškova" u tabovima. Cijene rada, praznici i godišnji plan su pod "Podešavanja obračuna".',
  'guide.usage.step8':
    'Sve što traži odluku (radni sati, odsustva, troškovi vozila, kvarovi) ima crveni broj u meniju i šalje obavještenje onome ko može odlučiti. Troškovi se odobravaju ili vraćaju sa razlogom; svoj unos ne možete odobriti sami (Super Admin može). Pogrešnu odluku možete poništiti dugmetom "Vrati na čekanje".',
  'guide.usage.step9':
    'Liste nemaju brojeve stranica: dugme "Prikaži još" otvara sljedeće redove. Odsustva i troškovi vozila imaju i prikaz "Tabla", po jedna kolona za svaki status, pored prikaza "Lista".',
  'guide.usage.step10':
    'Na telefonu se svaka lista pretvara u kartice, sa istim akcijama i izborom sortiranja na vrhu.',
  'guide.role.superAdmin.name': 'Super Admin',
  'guide.role.superAdmin.description':
    'Pun pristup cijeloj platformi, uključujući Podešavanja firme i slobodnu Evidenciju. Vodi sistem u cjelini.',
  'guide.role.admin.name': 'Admin',
  'guide.role.admin.description':
    'Svakodnevno upravljanje: radnici, gradilišta, vozila, alati, materijali, troškovi i korisnički nalozi. Nema pristup Podešavanjima firme ni Evidenciji — samo Super Admin.',
  'guide.role.projectManager.name': 'Rukovodilac projekta',
  'guide.role.projectManager.description':
    'Upravlja gradilištima i materijalima, odobrava zahtjeve za odsustvo, pregledava evidentirano radno vrijeme i troškove vozila. Nema pristup platama ni podešavanjima firme.',
  'guide.role.foreman.name': 'Poslovođa',
  'guide.role.foreman.description':
    'Vodi jedno gradilište iz dana u dan — pregleda radno vrijeme svoje ekipe, odsustva i prijavljene kvarove. Evidentira gorivo i ostale troškove vozila (pregleda ih menadžer). Koristi vozila, alate i materijale, ne dodaje nove.',
  'guide.role.worker.name': 'Radnik',
  'guide.role.worker.description':
    'Koristi mobilnu aplikaciju na terenu — prijavljuje dolazak i odlazak s posla, prijavljuje kvarove, predaje sedmične izvještaje i traži odsustvo. Nema pristup ovom admin panelu.',
  'guide.role.customer.name': 'Klijent',
  'guide.role.customer.description':
    'Spoljni klijent, ne zaposleni — prijavljuje se na posebnu adresu (/customer) na stranicu koja pokazuje samo status i napredak njegovog projekta, ništa drugo: bez cijena, bez plata, bez pristupa ovom admin panelu. Da biste ga podesili: napravite korisnika na stranici Korisnici, izaberite ulogu Klijent i povežite ga sa zapisom klijenta umjesto sa zaposlenim.',
