  'releaseNotes.title': 'Šta je novo — {date}',
  'releaseNotes.intro': 'Na platformi je urađeno nekoliko promjena. Ovo je kratak pregled onoga što se tiče vas.',
  'releaseNotes.close': 'Razumijem',


  'releaseNotes.dnd1020.title': "Raspored: povlačenje radnika",
  'releaseNotes.dnd1020.drag': "U Rasporedu (Po gradilištima i Vremenska traka) radnika možete povući na gradilište, na drugog radnika (zamjena) ili među Slobodne. Gradilišta kojima fali njegova vještina svijetle zeleno. Na telefonu ga zadržite prstom, a običan dodir i dalje otvara prozor radnika.",
  'releaseNotes.dnd1020.window': "Nakon puštanja otvara se prozor koji piše radnika, gradilište i datume (radne dane), a razdoblje se može produžiti: samo taj dan, do kraja sedmice, do kraja gradilišta ili po izboru. Piše šta se mijenja (npr. koje gradilište ostaje bez vještine), a tek Potvrdi mijenja raspored. Poništi radi kao i prije.",
  'releaseNotes.dnd1020.timeline': "U vremenskoj traci se povlači traka radnika (cijeli period) na gradilište iz trake iznad tabele, ili na ime drugog radnika za zamjenu. Odsustva se ne mogu povlačiti.",
  'releaseNotes.dark1018.title': "Tamna tema: logo firme",
  'releaseNotes.dark1018.logo': "Logo firme na tamnoj temi više nije crn na tamnoj pozadini: u gornjoj traci, meniju, pregledu loga i na prijavi prikazuje se svijetao, bez bijelog pravougaonika iza njega. Na svijetloj temi se ništa ne mijenja.",
  'releaseNotes.home1018.title': "Početna: manje na ekranu",
  'releaseNotes.home1018.fewer': "Novi nalozi na početnoj dobijaju šest widgeta koji se gledaju svaki dan (Zahtijeva pažnju, Prisutnost, Ključni pokazatelji, Narudžbe, Finansije, Zahtjevi za odsustvo), umjesto svih odjednom. Ostalo je u „Dodaj widget”. Sačuvan raspored se ne mijenja.",
  'releaseNotes.home1018.strips': "Widget kojem nema šta da pokaže (nema dokumenata koji ističu, nema projekata van budžeta, nema poslovnih jedinica) postaje tanka traka s jednom rečenicom i kvačicom, a čim ima sadržaja, sam se proširi. Na računaru kartica je visoka koliko njen sadržaj; ako je sami razvučete, ostaje kakvu ste je namjestili.",
  'releaseNotes.home1018.finance': "Pet finansijskih widgeta (pregled, statistika, trend troškova, trend potrošnje, na šta odlazi novac) je sada jedan, Finansije, s tabovima Pregled, Trend i Struktura. Postojeći rasporedi dobijaju jednu karticu na mjestu prve, otvorenu na onom što je pokazivala. Nalog koji smije vidjeti samo postotke dobija postotke.",
  'releaseNotes.home1018.small': "„Podešavanje sistema” je mala značka desno iznad widgeta, koju možete sakriti dok se ne pojavi nešto novo. Na telefonu je widget ispod kartice „Danas” sada „Još čeka” i ne ponavlja ono što kartica već nabraja. Datum piše „nedjelja”, ne „nedelja”.",
  'releaseNotes.home1018.exact': "Brojevi na početnoj su provjereni s bazom. Ispravljeno: trake u „Projekti — realizacija” su bile gotovo prazne (98% je prikazano kao 1%); brojevi vozila, alata, projekata, narudžbi i smjena više ne staju na prvih 100 redova; „danas” i „ovaj mjesec” se računaju po lokalnom datumu (u prva dva sata iza ponoći su se računali po jučerašnjem); mjeseci u grafikonu više ne počinju dan ranije; sati danas uključuju smjene koje još traju; trošak ovog mjeseca se poredi s istim danima prošlog mjeseca, ne s cijelim mjesecom; brojevi radnika, vozila, alata, projekata, narudžbi i smjena poštuju izabranu poslovnu jedinicu.",
  'releaseNotes.home1018.zone': "Vremenska zona je sada podešavanje organizacije (Podešavanja firme, SuperAdmin) i cijela platforma računa dan po njoj: server, izvještaji, ovaj panel i aplikacija. Smjena koja počne u 00:30 u subotu je subotnja (i cijeni se po subotnjoj stopi), „danas” se mijenja u ponoć organizacije, a ne u ponoć telefona ili računara, a vremena prijave se prikazuju na satu organizacije. Promjena važi odmah.",
  'releaseNotes.home1018.app': "Aplikacija 1.1.34 (Android) ide uz ovo izdanje: dan, današnji datum, podsjetnici za smjenu i vremena prijave računaju se po vremenskoj zoni organizacije, a ne po satu telefona. Preuzima se sa stranice za preuzimanje.",
  'releaseNotes.home1018.docs': "Svaki widget ima znak „?” koji vodi na objašnjenje čemu služi i kako se računa svaki njegov broj (Pomoć, teme Widgeti). Zahtijeva pažnju, Dokumenti koji ističu i meni se sada sužavaju na izabranu poslovnu jedinicu.",
  'releaseNotes.since1018.title': "Početna: šta se promijenilo od jučer",
  'releaseNotes.since1018.notes': "Uz brojeve na početnoj piše koliko su veći ili manji nego jučer, npr. +2 od jučer: u Zahtijeva pažnju i kartici Danas na telefonu, uz aktivne radnike, otvorene radne naloge, vozila, alate i narudžbe. Zelena boja je bolje, crvena lošije.",
  'releaseNotes.since1018.rules': "Poredi se s onim što je vaš nalog vidio jučer, pa se natpisi pojave drugog dana korištenja. Pamti se samo broj i dan, i čuva tri dana. Sa izabranom poslovnom jedinicom poredi se s jučerašnjim brojevima te jedinice.",
  'releaseNotes.widgets1017.title': "Novi izgled widgeta, meni na telefonu",
  'releaseNotes.widgets1017.look': "Svi widgeti na početnoj imaju novi izgled: kartica bez okvira, kontrole (premjesti, uvećaj, ukloni) se pokažu tek preko kartice, krupni brojevi, liste sa obojenim stanjem i brojem, trake i tabele u istom stilu.",
  'releaseNotes.widgets1017.size': "Širenje, premještanje i visina svakog widgeta rade kao i prije. Sadržaj se prilagođava širini koju widget dobije: na širokom monitoru se širi u kolone i krupnije brojeve, na telefonu se slaže u jednu kolonu, svaki widget visok koliko mu je sadržaj. Natpisi i oznake se nikad ne preklapaju niti izlaze iz kartice: duge se prelome u novi red, a veliki iznosi se smanje da stanu u jedan red (nikad se ne lome usred broja). Grafikon Prihod i rashod na telefonu više ne raste preko cijelog ekrana.",
  'releaseNotes.widgets1017.charts': "Prisutnost je prsten (koliko od aktivnih je na terenu), Radna snaga je broj s trakom i trakama po projektima, a trendovi u kartici Finansije su linija koju možete preći prstom da pročitate mjesec i iznos. Struktura troška je prsten sa spiskom, Vozila i alati su trake stanja. Uz trošak ovog mjeseca piše koliko je više ili manje nego prošli mjesec.",
  'releaseNotes.widgets1017.menu': "Meni u pregledniku telefona se otvara preko cijelog ekrana: pretraga na vrhu, brzi pristup, grupe kao krupne pločice s brojem, a na dnu poslovna jedinica, jezik, tema i odjava. Meni na računaru je isti.",
  'finance.budget.warnPercentHelp': 'Prazno znači 80%. Od 100% se projekat računa kao prekoračen.',
  'finance.housingDoubleWarning': '{count} troškova smještaja pada na dane kada je kirija već uračunata iz cijena smještaja, pa se ta kirija računa dvaput. Obrišite ih ili ih prebacite u drugu kategoriju.',
  'finance.payOverlapWarning': '{count} isplata bez projekta pada na dane kada je ista osoba evidentirala sate na projektu. Računaju se oba iznosa — provjerite treba li jedan zamijeniti drugi.',
