  'planning.tour.timeline.body': "Svaki red je radnik. Obojena traka je gradilište, šrafirano je odsustvo (GO godišnji, BO bolovanje), isprekidano je slobodan. Na dnu redovi Slobodno i Nedostaje pokazuju za svaki period koliko ljudi još možete rasporediti i koliko gradilištima fali.",
  'planning.tour.bar.title': "Klik za premještanje ili zamjenu",
  'planning.tour.bar.body': "Klik na traku otvara prozor u kojem radnika možete rasporediti na drugo gradilište, osloboditi ili zamijeniti drugim, za jedan dan ili cijelo razdoblje koje izaberete. Svaka izmjena ima dugme Poništi.",
  'planning.tour.need.title': "Potreba po projektima",
  'planning.tour.need.body': "Svaka ćelija je najgori dan u tom periodu: koliko radnika ima prema koliko treba. Zeleno je pokriveno, žuto fali dio, crveno nema nikoga. Klik na ćeliju pokazuje slobodne radnike prave vještine.",
  'planning.tour.editNeeds.title': "Recite šta projekat treba",
  'planning.tour.editNeeds.body': "Olovka pored projekta unosi koliko radnika koje vještine treba (npr. 2 zidara i 1 električar). Strelica pored nje pokazuje projekat po vještinama. Novi projekat se pravi na stranici Projekti, a njegova potreba se unosi ovdje.",
  'planning.tour.skills.title': "Manjak po vještinama",
  'planning.tour.skills.body': "Pokazuje gdje manjak mogu popuniti slobodni radnici, a gdje ne mogu, pa se vidi koje vještine treba angažovati ili posuditi.",
  'planning.tour.cover.title': "Treba zamjenu",
  'planning.tour.cover.body': "Odobrena odsustva u narednih 30 dana zbog kojih gradilištu fali neka vještina. Nađi zamjenu predlaže redom: ista vještina i slobodan, pa neko s gradilišta koje ima više te vještine nego što mu treba. Zamjenik ide samo za dane odsustva. Isti prijedlozi se nude i pri odobravanju odsustva.",
  'planning.tour.day.title': "Po gradilištima, za jedan dan",
  'planning.tour.day.body': "Kartica za svako gradilište s ekipom i brojačem. Isprekidano mjesto je pozicija koja još fali, s nazivom vještine; klik pokazuje ko bi mogao doći. Slobodni i odsutni su s desne strane.",
  'planning.tour.list.title': "Lista",
  'planning.tour.list.body': "Najbrži način da sredite jedan dan: gradilište za svakog radnika birate direktno iz padajućeg izbora.",
  'planning.tour.done.title': "To je sve",
  'planning.tour.done.body': "Vodič možete pokrenuti ponovo bilo kada dugmetom Vodič kroz Raspored na vrhu stranice.",
  'planning.title': "Raspored",
