  'book.guide.title': 'Evidencija umjesto Excel liste',
  'book.guide.intro': 'Šta ulazi, šta izlazi i šta ostaje, na jednom mjestu i bez formula koje se pokvare. Ova stranica objašnjava šta koji dio radi; ista objašnjenja stoje i na samim ekranima, u rubrici "Kako ovo radi".',
  'book.guide.step': 'Korak {number}',
  'book.guide.open': 'Otvori',
  'book.guide.step.one.title': 'Pogledajte dobit i tok novca',
  'book.guide.step.one.text': 'Naslovni ekran: šta ulazi, šta izlazi, šta ostaje, i šta traži vašu pažnju.',
  'book.guide.step.two.title': 'Upišite prvi trošak',
  'book.guide.step.two.text': 'Brzi unos s prečicama. Pogledajte kako se odmah promijene zbirovi.',
  'book.guide.step.three.title': 'Pogledajte obračun mjeseca',
  'book.guide.step.three.text': 'Promijenite način naplate ili sate i gledajte zaradu firme.',
  'book.guide.idea': 'Ideja u tri rečenice',
  'book.guide.ideaText': 'Svaki prihod, trošak, uplata i isplata upiše se samo jednom, kao jedan red u Knjizi. Sve ostalo (zbirovi, dobit, ko nam duguje, obračun mjeseca) program računa sam iz tih redova. Zato više nema formula koje se pokvare i sekcija koja izostane iz zbira.',
  'book.guide.month': 'Kako izgleda jedan mjesec',
  'book.guide.monthHelp': 'Pet koraka, od prvog dana do izvoza za knjigovođu.',
  'book.guide.month.enter.title': 'Unesite',
  'book.guide.month.enter.text': 'Brzi unos u Knjizi. Gorivo, smještaj i vozila dolaze sami.',
  'book.guide.month.compute.title': 'Program računa',
  'book.guide.month.compute.text': 'Prihodi, troškovi, dobit i obračun po gradilištima.',
  'book.guide.month.check.title': 'Provjeri',
  'book.guide.month.check.text': 'Lista "Za provjeru" pokaže šta ne štima.',
  'book.guide.month.lock.title': 'Zaključaj',
  'book.guide.month.lock.text': 'Mjesec se više ne mijenja, svaka ispravka ostavlja trag.',
  'book.guide.month.export.title': 'Izvezi',
  'book.guide.month.export.text': 'Excel za knjigovođu, iste brojke kao na ekranu.',
  'book.guide.functions': 'Šta koja funkcija radi',
  'book.guide.functionsHelp': 'Isto objašnjenje stoji i na samim ekranima, u rubrici "Kako ovo radi".',
  'book.guide.col.function': 'Funkcija',
  'book.guide.col.what': 'Šta radi',
  'book.guide.col.example': 'Primjer',
  'book.guide.fn.overview.name': 'Pregled novca i dobiti',
  'book.guide.fn.overview.what': 'Naslovni ekran: ulaz, izlaz i dobit za izabrani period, s prikazom "od sati do dobiti", grafikonom po mjesecima i statistikom troškova.',
  'book.guide.fn.overview.example': 'Izaberite "Zadnja 3 mjeseca" ili ručno Od i Do.',
  'book.guide.fn.cashflow.name': 'Tok novca u narednim danima',
  'book.guide.fn.cashflow.what': 'Redoslijed očekivanih uplata i isplata. Pokaže kad plata radnika izlazi prije naplate klijenta i da li stanje pada ispod nule.',
  'book.guide.fn.cashflow.example': 'Upišite koliko imate na računu i vidite najnižu tačku.',
  'book.guide.fn.forecast.name': 'Procjena sljedećeg mjeseca',
  'book.guide.fn.forecast.what': 'Predviđa ulaz, izlaz i dobit iz prosjeka zadnja tri zaključana mjeseca. Sate možete mijenjati.',
  'book.guide.fn.forecast.example': '"Šta ako u novembru radimo 3.500 sati?"',
  'book.guide.fn.quick.name': 'Brzi unos',
  'book.guide.fn.quick.what': 'Jedan red na vrhu Knjige: datum, vrsta, opis, gradilište, druga strana, iznos.',
  'book.guide.fn.quick.example': '"Gorivo sedmica 41, 1.980 €" i zbir se odmah promijeni.',
  'book.guide.fn.kinds.name': 'Vrste zapisa',
  'book.guide.fn.kinds.what': 'Prihod (izdata faktura) i trošak mijenjaju dobit. Uplata i isplata samo mijenjaju ko kome šta duguje.',
  'book.guide.fn.kinds.example': 'Uplata klijenta smanjuje otvorena potraživanja, ali dobit ostaje ista.',
  'book.guide.fn.source.name': 'Izvor zapisa',
  'book.guide.fn.source.what': 'Oznaka odakle red dolazi: ručno, DKV izvod, smještaj, vozila, šablon.',
  'book.guide.fn.source.example': 'DKV gorivo i kirija stana nastaju sami, ne upisujete ih.',
  'book.guide.fn.filters.name': 'Filteri',
  'book.guide.fn.filters.what': 'Prikaz samo prihoda, troškova, uplata ili isplata, i pretraga po opisu ili strani.',
  'book.guide.fn.filters.example': '"Samo troškovi" i upišite "gorivo".',
  'book.guide.fn.receivables.name': 'Ko nam duguje, kome dugujemo',
  'book.guide.fn.receivables.what': 'Otvorene fakture klijentima, plata radnika i računi dobavljača, s rokovima i kašnjenjem.',
  'book.guide.fn.receivables.example': '"Označi plaćeno" prebacuje fakturu u plaćene i mijenja zbirove.',
  'book.guide.fn.settlement.name': 'Obračun mjeseca',
  'book.guide.fn.settlement.what': 'Tabela po gradilištima kao u Excelu, ali izračunata iz Knjige. Sate upisujete iz potpisanih satnica.',
  'book.guide.fn.settlement.example': 'Promijenite sate na Hali B i vidite maržu, rezultat i zaradu firme.',
  'book.guide.fn.billing.name': 'Način naplate po gradilištu',
  'book.guide.fn.billing.what': 'Za svako gradilište birate: satnica (sati × cijena), paušal ili mjerenje (iznos izdatih faktura). Program pokaže i koliko bi bilo po satnici.',
  'book.guide.fn.billing.example': 'Zgrada D je paušal; prebacite je na satnicu i vidite razliku.',
  'book.guide.fn.payouts.name': 'Akontacije i konačna isplata',
  'book.guide.fn.payouts.what': 'Akontacija može biti više puta u mjesecu, bilo kome, gotovinom ili prenosom. Konačna isplata = zarada minus akontacije, s datumom i načinom po grupi.',
  'book.guide.fn.payouts.example': 'Dodajte dvije akontacije radnicima i vidite šta ostaje.',
  'book.guide.fn.recurring.name': 'Ponavljajući troškovi',
  'book.guide.fn.recurring.what': 'Šablon za trošak koji se ponavlja (kirija, fiksni troškovi, zakup, osiguranje). Program ga sam upisuje u Knjigu svakog mjeseca.',
  'book.guide.fn.recurring.example': 'Dodajte šablon i pogledajte šta nastaje u novembru.',
  'book.guide.fn.categories.name': 'Kategorije i pravila',
  'book.guide.fn.categories.what': 'Kategorija kaže o kakvom je novcu riječ i u koji dio obračuna ide. Pravila pogađaju kategoriju iz opisa.',
  'book.guide.fn.categories.example': 'Upišite "Gorivo, DKV izvod" i vidite šta program predloži.',
  'book.guide.fn.import.name': 'Uvoz iz Excela',
  'book.guide.fn.import.what': 'Prebacuje stare mjesece iz tabele u četiri koraka, s provjerom svakog reda prije upisa.',
  'book.guide.fn.import.example': 'Učitajte primjer, ispravite kolonu i pogledajte greške.',
  'book.guide.fn.checks.name': 'Za provjeru',
  'book.guide.fn.checks.what': 'Lista stvari koje treba pogledati prije zaključivanja: previše sati, paušal bez fakture, kašnjenje.',
  'book.guide.fn.checks.example': 'Označite jednu kao riješenu i vidite kako se otključava zaključavanje.',
  'book.guide.fn.lock.name': 'Zaključaj mjesec',
  'book.guide.fn.lock.what': 'Poslije zaključavanja brojke se ne mijenjaju. Ispravka traži otključavanje i upisuje ko je i kada.',
  'book.guide.fn.lock.example': 'Zaključaj oktobar kad su sve kućice označene.',
  'book.guide.not': 'Šta program ne radi',
  'book.guide.notText': 'Ne vodi porez, PDV ni doprinose, i nije zamjena za knjigovođu. Ovo je vaša evidencija novca; knjigovođa i dalje radi zvanično knjigovodstvo, a od nas dobija uredan izvoz.',
  'bookImport.subtitle': 'Prebaci stare mjesece iz tabele, bez prekucavanja',
  'bookImport.startOver': 'Počni ispočetka',
  'bookImport.how1': 'Uvoz ide u četiri koraka: izaberete datoteku, program pogodi koja kolona je šta (vi ispravite ako pogriješi), pregledate šta će se desiti, pa potvrdite.',
  'bookImport.how2': 'Prije nego što se išta upiše, program provjerava svaki red: da li su sati brojevi, da li se radnik ponavlja, da li ima cijenu, da li je radnik poznat.',
  'bookImport.how3': 'Upozorenje (žuto) se uvozi, ali ga treba pogledati. Greška (crveno) se ne uvozi, osim ako je ispravite u Excelu pa učitate ponovo.',
  'bookImport.how4': 'Uvoz se može ponoviti bez dupliranja: red koji već postoji se prepoznaje i ne upisuje drugi put.',
  'bookImport.how5': 'Uvezeni mjeseci ulaze u Obračun mjeseca i u Pregled, pa odmah dobijaš istoriju za grafikone i procjene.',
