  'book.categories.pageTitle': 'Kategorije',
  'book.categories.subtitle': 'Šta je koja vrsta prihoda i troška i gdje ulazi u obračun',
  'book.categories.how1': 'Kategorija kaže o kakvom je novcu riječ (gorivo, stanovanje, alat, naplata klijentu). Svaki red u Knjizi ima tačno jednu kategoriju.',
  'book.categories.how2': '"Ide u" određuje gdje se kategorija računa u obračunu mjeseca: u naplatu, zaradu radnika, troškove gradilišta ili fiksne troškove. Zato je bitno da kategorija bude tačna: ona odlučuje u koju kolonu padne iznos.',
  'book.categories.how3': 'Sistemske kategorije (Gorivo, Stanovanje, Rent a car, Plata radnika) pune se same iz DKV izvoda, smještaja, vozila i satnica. Možete ih preimenovati, ali ne i isključiti.',
  'book.categories.how4': 'Svoje kategorije pravite kad vam zatrebaju i možete ih isključiti. Isključena kategorija se ne nudi pri novom unosu, a stari zapisi ostaju.',
  'book.categories.how5': 'Pravila pogađaju kategoriju iz opisa: ako opis sadrži "DKV", program predloži Gorivo. Tako se ručni unos ubrzava. Isprobajte pogađanje u polju ispod.',
