  'book.recurring.title': 'Ponavljajući troškovi',
  'book.recurring.subtitle': 'Upišite jednom, program ih sam stavlja u Knjigu svakog mjeseca',
  'book.recurring.how1': 'Za trošak koji se ponavlja (kirija, fiksni troškovi po zemlji, zakup vozila, osiguranje) napraviš šablon: iznos, koliko često i koji dan u mjesecu.',
  'book.recurring.how2': 'Prvog dana u mjesecu program iz svakog aktivnog šablona napravi red u Knjizi, s oznakom izvora "Šablon". Ništa ne moraš kucati.',
  'book.recurring.how3': 'Iznos možete promijeniti u svakom trenutku. Promjena važi od sljedećeg mjeseca, a već napravljeni zapisi ostaju kakvi jesu.',
  'book.recurring.how4': 'Šablon koji više ne treba ne briše se, nego isključi. Stari zapisi zbog toga ostaju u evidenciji.',
  'book.recurring.how5': 'Dolje je pregled sljedećeg mjeseca: vidite šta će nastati i koliko ukupno, prije nego što se desi.',
