  'book.settlement.export': 'Izvoz u Excel',
  'book.settlement.sheet': 'Otvori tabelu obračuna',
  'book.settlement.lockedBanner': 'Mjesec je zaključan. Brojke se ne mogu mijenjati. Ako treba ispravka, otključaš mjesec, a program upiše ko je i kada to uradio.',
  'book.settlement.how1': 'Ovo je vaša Excel tabela, ali se računa sama. Svako gradilište je jedan red, a zbir uvijek obuhvata sve redove.',
  'book.settlement.how2': 'Način naplate se bira za svako gradilište. Satnica: naplata = sati × cijena za klijenta. Paušal i Mjerenje: naplata je iznos izdatih faktura za mjesec, a sati služe da se vidi da li se posao isplati.',
  'book.settlement.how3': 'Promijenite način naplate za Halu B ili Zgradu D pa gledajte kako se mijenjaju naplata, marža i zarada firme. Ispod tabele program pokaže koliko bi bilo po satnici u odnosu na paušal.',
  'book.settlement.how4': 'Zarada radnika = sati × cijena radnika. Marža = naplata − zarada radnika. Rezultat = marža − troškovi gradilišta. Zarada firme = rezultat svih gradilišta − fiksni troškovi.',
  'book.settlement.how5': 'Zaključavanje je moguće tek kad su sve kućice označene, a to uključuje i da su sve stavke "Za provjeru" riješene.',
