  'payouts.subtitle': 'Zarada za {month}, akontacije i konačna isplata',
  'payouts.how1': 'Zarada dolazi iz Obračuna mjeseca, odvojeno za radnike, kooperante i kancelariju.',
  'payouts.how2': 'Akontacija može biti koliko god puta u mjesecu, bilo kome i bilo kojim načinom (bankovni prenos ili gotovina). Svaka se upiše sa datumom i smanji ono što ostaje za konačnu isplatu.',
  'payouts.how3': 'Konačna isplata = zarada minus sve akontacije. Datum i način birate za svaku grupu posebno, pa kooperanti mogu dobiti novac kasnije nego radnici.',
  'payouts.how4': 'Ako je akontacija veća od zarade, program upozori; višak se prenosi u sljedeći mjesec.',
  'payouts.how5': 'Isplata ne mijenja dobit, jer je trošak rada već u obračunu. Mijenja samo tok novca: pokaže koliko treba imati na računu na dan isplate.',
