  'book.receivables.asOf': 'Stanje na dan {date}',
  'book.receivables.how1': 'Gornja tabela su fakture koje smo izdali, a klijent ih još nije platio. Kad klijent plati, klik na Označi plaćeno potvrđuje uplatu: faktura izlazi iz otvorenih i zbir se smanji.',
  'book.receivables.how2': 'Kasni znači da je rok prošao. Dugme za opomenu priprema poruku klijentu.',
  'book.receivables.how3': 'Mi dugujemo: plata radnika je obračunata zarada minus akontacija koju smo već isplatili, plus računi dobavljača koje nismo platili.',
  'book.receivables.how4': 'Razlika pokazuje da li imamo dovoljno ulaza da pokrijemo ono što dugujemo, kad klijenti plate.',
