  'book.entries.export': 'Izvoz za knjigovođu',
  'book.entries.how1': 'Jedan unos, sve se računa samo. Upišite red u Brzi unos i kućice iznad (prihodi, troškovi, dobit, potraživanja) odmah se promijene.',
  'book.entries.how2': 'Prihod je izdata faktura: povećava prihode i otvorena potraživanja. Trošak povećava troškove.',
  'book.entries.how3': 'Uplata (klijent platio) smanjuje otvorena potraživanja, a Isplata (npr. akontacija radnicima) samo bilježi da je novac otišao. Ni jedno ni drugo ne mijenja dobit, jer su prihod i trošak već upisani.',
  'book.entries.how4': 'Izvor kaže odakle red dolazi. Zapisi iz DKV izvoda, smještaja i vozila nastaju sami; ručno upisujete samo ostalo. Njihova olovka je strelica: mijenjaju se tamo gdje su nastali.',
  'book.entries.how5': 'Izvoz s dokumentima preuzima ZIP: tabelu zapisa koje si filtrirao i po jednu mapu za svaki zapis koji ima dokumente (naziv: datum, opis i iznos). Pošalji ga knjigovođi kakav jeste.',
