  'book.overview.quick.settlementHelp': 'Način naplate po gradilištu, provjere i zaključavanje mjeseca.',
  'book.overview.how1': 'Ulaz je ono što klijenti plate za odrađene sate. Izlaz su plate radnika, kooperanti, kancelarija, troškovi gradilišta (gorivo, stanovi, vozila, alat) i fiksni troškovi. Dobit je ulaz minus izlaz.',
  'book.overview.how2': 'Period birate dugmadima ili ručno ("Od" i "Do"). Sve kućice i grafikoni na ovom ekranu prate izabrani period. Klik na mjesec u grafikonu bira baš taj mjesec.',
  'book.overview.how3': 'Tok novca u narednim danima pokazuje redoslijed uplata i isplata. Radnike plaćate prije nego što klijent plati, pa stanje može privremeno pasti ispod nule. Upišite koliko imate na računu i vidite gdje je najniža tačka.',
  'book.overview.how4': 'Procjena sljedećeg mjeseca se računa iz prosjeka zadnja tri zaključana mjeseca (cijena i trošak po satu), a fiksni troškovi i kancelarija ostaju isti. To je procjena, ne obećanje. Promijenite sate da vidite "šta ako".',
